    // Base velocity in the yaw-aligned frame, in m/s.
    const bvx = c * wvx + sn * wvy;
    const bvy = -sn * wvx + c * wvy;
    const bx = base[0] as number, by = base[1] as number;
    const lim = (v: number) => Math.max(-REFLEX_LIMITS.v, Math.min(REFLEX_LIMITS.v, v));

    const ex = bvx - bx;
    if (Math.abs(ex) > LATCH_TRIGGER) { this.latchUntil = s.t + LATCH_HOLD; this.latchDir = Math.sign(ex); }
    out[0] = s.t < this.latchUntil ? lim(bx + this.latchDir * LATCH_STEP) : bx;

    const ey = bvy - by;
    const dy = Math.abs(ey) <= LATERAL_DEADBAND ? 0 : ey - Math.sign(ey) * LATERAL_DEADBAND;
    out[1] = lim(by + LATERAL_GAIN * dy);
    out[2] = base[2] as number;
  }
}

const ENV = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env ?? {};
const num = (k: string, d: number) => (ENV[k] !== undefined ? Number(ENV[k]) : d);
/** Lateral step-into-push gain, dimensionless. */
const LATERAL_GAIN = num('RX_GY', 1.0);
/** Lateral speed error below which the reflex stays idle, in m/s. */
const LATERAL_DEADBAND = num('RX_DB', 0.1);
/** Forward speed error that triggers the sagittal latch, in m/s. */
const LATCH_TRIGGER = num('RX_TH', 0.6);
/** Duration of the sagittal latch after the last trigger, in s. */
const LATCH_HOLD = num('RX_HOLD', 0.6);
/** Command offset applied while latched, in m/s. */
const LATCH_STEP = num('RX_STEP', 1.0);

/** Command limits the Walker applies after the reflex. */
export const REFLEX_LIMITS = { v: 1.0, yaw: 1.0 } as const;
